using UnityEditor;
using UnityEditor.Build;
using UnityEngine;

/// <summary>
/// Applies the Subway Karma app icons and splash screen to Player Settings.
///
///   Tools → Subway Karma → Apply App Icons and Splash Screen
///
/// Run it once after cloning (or whenever the artwork in Assets/Art/Branding
/// changes), then commit ProjectSettings/ProjectSettings.asset and the .meta
/// files. The artwork is generated by tools/make_branding.py.
///
/// Uses the PlayerSettings API instead of hand-editing ProjectSettings.asset,
/// so Unity writes the icon and splash data in its own format.
/// </summary>
public static class BrandingSetup
{
    private const string Dir            = "Assets/Art/Branding/";
    private const string IconPath       = Dir + "AppIcon.png";
    private const string ForegroundPath = Dir + "AppIcon_AdaptiveForeground.png";
    private const string BackgroundPath = Dir + "AppIcon_AdaptiveBackground.png";
    private const string SplashPath     = Dir + "SplashLogo.png";

    private const float SplashLogoSeconds = 2.5f;
    private static readonly Color SplashBackground = new Color32(0x1F, 0x1F, 0x20, 0xFF);

    [MenuItem("Tools/Subway Karma/Apply App Icons and Splash Screen")]
    public static void Apply()
    {
        ConfigureTexture(IconPath,       asSprite: false);
        ConfigureTexture(ForegroundPath, asSprite: false);
        ConfigureTexture(BackgroundPath, asSprite: false);
        ConfigureTexture(SplashPath,     asSprite: true);

        var icon       = AssetDatabase.LoadAssetAtPath<Texture2D>(IconPath);
        var foreground = AssetDatabase.LoadAssetAtPath<Texture2D>(ForegroundPath);
        var background = AssetDatabase.LoadAssetAtPath<Texture2D>(BackgroundPath);
        var splash     = AssetDatabase.LoadAssetAtPath<Sprite>(SplashPath);

        if (icon == null)
        {
            Debug.LogError($"[BrandingSetup] Missing {IconPath}. Is Git LFS installed (git lfs pull)?");
            return;
        }

        // Default icon: used by every platform that has no override (Windows .exe, macOS, Linux,
        // Web favicon, iOS, Android legacy/round icons).
        PlayerSettings.SetIcons(NamedBuildTarget.Unknown, new[] { icon }, IconKind.Any);

        // Android 8+ adaptive icon (separate background and foreground layers).
        if (foreground != null && background != null)
            ApplyAndroidAdaptiveIcon(background, foreground);

        // Splash screen: our title card on the board's charcoal, without the Unity logo
        // (optional in Unity 6 on every plan).
        PlayerSettings.SplashScreen.show            = true;
        PlayerSettings.SplashScreen.showUnityLogo   = false;
        PlayerSettings.SplashScreen.backgroundColor = SplashBackground;
        PlayerSettings.SplashScreen.unityLogoStyle  = PlayerSettings.SplashScreen.UnityLogoStyle.LightOnDark;
        PlayerSettings.SplashScreen.drawMode        = PlayerSettings.SplashScreen.DrawMode.AllSequential;
        if (splash != null)
            PlayerSettings.SplashScreen.logos = new[] { PlayerSettings.SplashScreenLogo.Create(SplashLogoSeconds, splash) };

        AssetDatabase.SaveAssets();
        Debug.Log("[BrandingSetup] App icons and splash screen applied. " +
                  "Commit ProjectSettings/ProjectSettings.asset and the Art/Branding .meta files.");
    }

    private static void ApplyAndroidAdaptiveIcon(Texture2D background, Texture2D foreground)
    {
        PlatformIconKind[] kinds = PlayerSettings.GetSupportedIconKinds(NamedBuildTarget.Android);
        if (kinds == null || kinds.Length == 0)
        {
            Debug.LogWarning("[BrandingSetup] Android Build Support isn't installed; skipped the adaptive icon. " +
                             "Android will use the default icon.");
            return;
        }

        foreach (PlatformIconKind kind in kinds)
        {
            if (!kind.ToString().Contains("Adaptive")) continue;

            PlatformIcon[] icons = PlayerSettings.GetPlatformIcons(NamedBuildTarget.Android, kind);
            foreach (PlatformIcon slot in icons)
                slot.SetTextures(background, foreground);   // layer 0 = background, layer 1 = foreground
            PlayerSettings.SetPlatformIcons(NamedBuildTarget.Android, kind, icons);
        }
    }

    private static void ConfigureTexture(string path, bool asSprite)
    {
        if (!(AssetImporter.GetAtPath(path) is TextureImporter importer))
        {
            Debug.LogError($"[BrandingSetup] Missing texture {path}.");
            return;
        }

        var type = asSprite ? TextureImporterType.Sprite : TextureImporterType.Default;
        bool changed = importer.textureType != type
                    || importer.mipmapEnabled
                    || importer.npotScale != TextureImporterNPOTScale.None
                    || importer.maxTextureSize < 2048
                    || (asSprite && importer.spriteImportMode != SpriteImportMode.Single);
        if (!changed) return;

        importer.textureType         = type;
        importer.alphaIsTransparency = true;
        importer.mipmapEnabled       = false;
        importer.npotScale           = TextureImporterNPOTScale.None;
        importer.maxTextureSize      = 2048;
        if (asSprite) importer.spriteImportMode = SpriteImportMode.Single;
        importer.SaveAndReimport();
    }
}
